export const COTS_STATUSES=['Need to order','Part ordered','Ordered','Part received','Received'];
export const toOrder=item=>Math.max(0,item.needed-item.ordered);
export function cotsStatus(item){if(item.received>=item.needed)return 'Received';if(item.received>0)return 'Part received';if(item.ordered>=item.needed)return 'Ordered';if(item.ordered>0)return 'Part ordered';return 'Need to order';}
export function validCots(items){return Array.isArray(items)&&new Set(items.map(i=>i?.id)).size===items.length&&items.every(i=>i&&['id','name','vendor','number','url','eta','reference','notes'].every(k=>typeof i[k]==='string'&&i[k].length<=10000)&&i.id&&i.name.trim()&&i.vendor.trim()&&['needed','ordered','received'].every(k=>Number.isSafeInteger(i[k])&&i[k]>=0)&&i.needed>0&&i.received<=i.ordered&&(!i.url||safeProductUrl(i.url))&&(!i.eta||/^\d{4}-\d{2}-\d{2}$/.test(i.eta)&&!Number.isNaN(Date.parse(i.eta))));}
export function safeProductUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
export function vendorName(value){const v=value.trim();if(/^mc\s*master(?:[\s-]*carr)?$/i.test(v))return 'McMaster-Carr';if(/^rev(?: robotics)?$/i.test(v))return 'REV';if(/^(wcp|westcoast products)$/i.test(v))return 'WCP';return v;}
export function wcpProduct(value){const u=new URL(value);if(u.protocol!=='https:'||!['wcproducts.com','www.wcproducts.com'].includes(u.hostname)||u.port||u.username||u.password)throw Error('Use a WCP product link.');const m=u.pathname.match(/(?:^|\/)products\/([a-z0-9-]+)\/?$/i);if(!m)throw Error('Use a WCP product page link.');return {handle:m[1],variant:u.searchParams.get('variant')||''};}
export function selectWcpVariant(variants,item){const product=wcpProduct(item.url);if(product.variant){const match=variants.find(v=>v.id===product.variant);if(!match||!match.sku)throw Error('Use the link for the specific WCP item, not its product group.');if(item.number.trim()&&match.sku.toLowerCase()!==item.number.trim().toLowerCase())throw Error('The part number does not match the selected product option.');return match;}const exact=variants.filter(v=>v.sku&&v.sku.toLowerCase()===item.number.trim().toLowerCase());if(exact.length===1)return exact[0];if(!item.number.trim()&&variants.length===1&&variants[0].sku)return variants[0];throw Error('Add the exact WCP part number and a link to the specific product option.');}
export function wcpCartLink(lines){const quantities=new Map();for(const line of lines){if(!/^\d+$/.test(line.variant)||!Number.isSafeInteger(line.quantity)||line.quantity<1)throw Error('Invalid cart item.');quantities.set(line.variant,(quantities.get(line.variant)||0)+line.quantity);}if(!quantities.size)throw Error('No items need ordering.');const url='https://wcproducts.com/cart/'+[...quantities].map(([id,qty])=>`${id}:${qty}`).join(',')+'?storefront=true';if(url.length>1900)throw Error('This order is too large for one cart link. Split it into smaller orders.');return url;}
export function orderList(items){return ['Part number\tName\tQty to order',...items.filter(i=>toOrder(i)>0).map(i=>[i.number,i.name,toOrder(i)].map(v=>String(v).replace(/[\t\r\n]/g,' ')).join('\t'))].join('\n');}
